<template><section class="library"><header><span>CREATOR CRM</span><h1>品牌达人资源库</h1><p>达人档案按租户隔离，首期不展示原始联系方式。</p></header><el-card shadow="never"><el-table v-loading="loading" :data="rows" empty-text="暂无达人档案"><el-table-column prop="code" label="达人编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="platform" label="平台"/><el-table-column prop="handle" label="账号"/><el-table-column prop="category" label="内容赛道"/><el-table-column prop="follower_count" label="粉丝数"/><el-table-column prop="cooperation_status" label="合作状态"/><el-table-column label="黑名单"><template #default="{row}">{{row.is_blacklisted?'是':'否'}}</template></el-table-column></el-table><el-pagination v-if="total > 0" v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" :total="total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="changePageSize"/></el-card></section></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{fetchInfluencers}from'../../api/influencers';import{collectionRows,collectionTotal}from'../../utils/businessResponse';const rows=ref([]),total=ref(0),page=ref(1),pageSize=ref(20),loading=ref(false);async function load(){loading.value=true;const r=await fetchInfluencers({page:page.value,page_size:pageSize.value});loading.value=false;if(r.success){rows.value=collectionRows(r.data);total.value=collectionTotal(r.data)}else{rows.value=[];total.value=0;ElMessage.error(r.message)}}function changePageSize(){page.value=1;load()}onMounted(load);</script>
<style scoped>.library{display:grid;gap:18px}header{padding:24px;border:1px solid #d8c59a;border-radius:16px;background:linear-gradient(135deg,#fffaf0,#f4ead3)}header span{font-size:11px;letter-spacing:.18em;color:#8a6425}h1{margin:6px 0;color:#392f20;font-size:30px}p{margin:0;color:#75664e}</style>
